def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    demand = 0.0
    for site in s.get('sites') or []:
        o = site.get('occupancy')
        o = max(0.0, o if o is not None else 1.0)
        total += o
        group = (props.get(site.get('element')) or {}).get('group')
        if group is None:
            continue
        if 15 <= group <= 17:
            demand += o * (18.0 - group)
        elif group == 1 or group == 2:
            demand -= o * group
        elif group == 13:
            demand -= 3.0 * o
    return demand / total if total > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    total = sum(occ)
    if total <= 0:
        return 0.0
    coordination = [0.0 for t in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0 and d <= 1.25 * (a + b):
                coordination[i] += occ[j]
    mean = sum(occ[i] * coordination[i] for i in range(n)) / total
    variance = sum(occ[i] * (coordination[i] - mean) ** 2 for i in range(n)) / total
    return sqrt(max(0.0, variance))

def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    occupied = 0.0
    sphere_volume = 0.0
    for site in s.get('sites') or []:
        o = site.get('occupancy')
        o = max(0.0, o if o is not None else 1.0)
        occupied += o
        r = (props.get(site.get('element')) or {}).get('covalent_radius_A')
        if r is not None and r > 0:
            sphere_volume += o * (4.0 * pi / 3.0) * r ** 3
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None or volume <= 0:
        vpa = s.get('volume_per_atom_A3')
        volume = vpa * occupied if vpa is not None and vpa > 0 else 0.0
    return sphere_volume / volume if volume > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    elements = [t.get('element') for t in sites]
    groups = [(props.get(t.get('element')) or {}).get('group') for t in sites]
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    total = sum(occ)
    if total <= 0:
        return 0.0
    bonds = [0.0 for t in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if not (0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6):
            continue
        g = groups[i]
        if g is None or not (15 <= g <= 17) or elements[i] != elements[j]:
            continue
        a = radii[i]
        b = radii[j]
        if a is None or b is None or a <= 0 or b <= 0 or d > 1.25 * (a + b):
            continue
        order = min(3.0, exp(min(1.1, (a + b - d) / 0.25)))
        bonds[i] += occ[j] * order
    demand = 0.0
    for i in range(n):
        g = groups[i]
        if g is None:
            continue
        if 15 <= g <= 17:
            demand += occ[i] * max(0.0, 18.0 - g - bonds[i])
        elif g == 1 or g == 2:
            demand -= occ[i] * g
        elif g == 13:
            demand -= 3.0 * occ[i]
    return demand / total
